# Added functions for new release

from itertools import combinations

# Basic utilities
_marker = object()

class UnequalIterablesError(ValueError):
    pass

# Consume items from iterable

def consume(iterable, n=None):
    if n is None:
        for _ in iterable:
            pass
    else:
        for _ in range(n):
            next(iterable)

# Flatten nested iterables

def flatten(iterable, map_func=None):
    if map_func is None:
        for item in iterable:
            if isinstance(item, (list, tuple)):
                for sub in item:
                    yield sub
            else:
                yield item
    else:
        for item in iterable:
            for sub in map_func(item):
                yield sub

# Pairwise iteration

def pairwise(iterable):
    a = iter(iterable)
    try:
        prev = next(a)
    except StopIteration:
        return
    for current in a:
        yield (prev, current)
        prev = current

# Powerset

def powerset(iterable):
    s = list(iterable)
    return chain.from_iterable(combinations(s, r) for r in range(len(s)+1))

# Take first n items

def take(n, iterable):
    return list(islice(iterable, n))

# Unique everseen

def unique_everseen(iterable, key=None):
    seen = set()
    for element in iterable:
        k = element if key is None else key(element)
        if k not in seen:
            seen.add(k)
            yield element

# All equal

def all_equal(iterable):
    it = iter(iterable)
    try:
        first = next(it)
    except StopIteration:
        return True
    return all(x == first for x in it)

# _zip_equal

def _zip_equal(*iterables):
    return zip(*iterables)

# Relative seek

def relative_seek(stream, offset, whence=0):
    if hasattr(stream, "tell") and hasattr(stream, "seek"):
        current = stream.tell()
        new_pos = current + offset
        return stream.seek(new_pos, 0)
    raise AttributeError("stream does not support tell/seek")

# Polynomial utilities

def polynomial_eval(coefficients, x):
    result = 0
    for coeff in coefficients:
        result = result * x + coeff
    return result

# Polynomial derivative

def polynomial_derivative(coefficients):
    n = len(coefficients)
    if n <= 1:
        return [0]
    return [coeff * (n - 1 - i) for i, coeff in enumerate(coefficients[:-1])]

# Sum of squares

def sum_of_squares(iterable):
    return sum(x * x for x in iterable)

# Partial product correction
# (implementation from more.py)

# nth combination with replacement
from itertools import combinations_with_replacement

def nth_combination_with_replacement(iterable, n, r=None):
    if r is None:
        r = len(iterable)
    return next(islice(combinations_with_replacement(iterable, r), n, None))

# combination_with_replacement_index

def combination_with_replacement_index(element, iterable):
    r = len(element)
    return list(combinations_with_replacement(iterable, r)).index(element)

# Update __all__
__all__ = [
    'relative_seek',
    'polynomial_eval',
    'polynomial_derivative',
    'sum_of_squares',
    'nth_combination_with_replacement',
    'combination_with_replacement_index',
    'consume',
    'flatten',
    'pairwise',
    'powerset',
    'take',
    'unique_everseen',
    'all_equal',
    'UnequalIterablesError',
    '_marker',
    '_zip_equal',
]

